{
    void Run(BlogContext context)
    {
        // Breaking change #4: EF 9 uses parameterized queries by default for Cosmos.
        // Raw SQL using the old "Discriminator" property name still works but must
        // reference the correct JSON property name we preserved above.
        var blogs = context.Blogs
            .FromSqlRaw("SELECT * FROM c WHERE c.Discriminator = 'Blog'")
            .ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking change #5: EF 9 enables sync I/O blocking by default on Cosmos.
        // If you hit "Synchronous operations are disallowed", use async:
        // await context.SaveChangesAsync();
        context.SaveChanges();
    }
}

