using Microsoft.EntityFrameworkCore;

class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change #4: Raw SQL must reference the preserved JSON property name.
        // In EF 9 Cosmos, use FromSql (FromSqlRaw still available via relational pkg).
        var blogs = context.Blogs
            .Where(b => EF.Property<string>(b, "$type") == "Blog")
            .ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

